// IL2CPP Runtime Dumper - Frida Script
// Generated by OprekTool v0.16.0
// This script runs INSIDE the game process via Frida
// It calls IL2CPP API functions directly to dump everything
//
// Usage: frida -U -f <package> -l il2cpp_frida_dump.js --no-pause

Java.perform(function() {
    console.log("[*] OprekTool IL2CPP Dumper v0.16.0");
    console.log("[*] Searching for IL2CPP runtime...");

    // Find IL2CPP module
    var il2cpp = null;
    var possibleNames = ["libil2cpp.so", "liblogic.so", "libUE4.so"];
    
    for (var i = 0; i < possibleNames.length; i++) {
        il2cpp = Process.findModuleByName(possibleNames[i]);
        if (il2cpp) {
            console.log("[+] Found: " + possibleNames[i] + " @ " + il2cpp.base);
            break;
        }
    }
    
    if (!il2cpp) {
        console.log("[-] IL2CPP library not found! Waiting 10s...");
        setTimeout(function() {
            for (var i = 0; i < possibleNames.length; i++) {
                il2cpp = Process.findModuleByName(possibleNames[i]);
                if (il2cpp) {
                    console.log("[+] Found after wait: " + possibleNames[i] + " @ " + il2cpp.base);
                    startDump();
                    return;
                }
            }
            console.log("[-] Still not found. Make sure the game is running.");
        }, 10000);
        return;
    }
    
    startDump();
    
    function startDump() {
        // Resolve IL2CPP API functions
        var exports = il2cpp.enumerateExports();
        var api = {};
        
        var neededAPIs = [
            "il2cpp_domain_get",
            "il2cpp_domain_get_assemblies",
            "il2cpp_assembly_get_image",
            "il2cpp_image_get_name",
            "il2cpp_image_get_class_count",
            "il2cpp_image_get_class",
            "il2cpp_class_get_name",
            "il2cpp_class_get_namespace",
            "il2cpp_class_get_type",
            "il2cpp_class_get_methods",
            "il2cpp_class_get_fields",
            "il2cpp_class_get_properties",
            "il2cpp_class_get_parent",
            "il2cpp_class_get_interfaces",
            "il2cpp_class_get_nested_types",
            "il2cpp_class_get_flags",
            "il2cpp_class_is_enum",
            "il2cpp_class_is_valuetype",
            "il2cpp_class_from_type",
            "il2cpp_class_get_method_from_name",
            "il2cpp_class_get_field_from_name",
            "il2cpp_method_get_name",
            "il2cpp_method_get_flags",
            "il2cpp_method_get_return_type",
            "il2cpp_method_get_param",
            "il2cpp_method_get_param_count",
            "il2cpp_method_get_param_name",
            "il2cpp_method_is_instance",
            "il2cpp_method_is_generic",
            "il2cpp_method_get_class",
            "il2cpp_type_get_name",
            "il2cpp_type_is_byref",
            "il2cpp_field_get_name",
            "il2cpp_field_get_type",
            "il2cpp_field_get_flags",
            "il2cpp_field_get_offset",
            "il2cpp_property_get_name",
            "il2cpp_property_get_get_method",
            "il2cpp_property_get_set_method",
            "il2cpp_string_chars",
            "il2cpp_thread_attach",
            "il2cpp_thread_current",
            "il2cpp_class_element_class",
            "il2cpp_class_get_rank",
            "il2cpp_class_get_method_count"
        ];
        
        for (var i = 0; i < exports.length; i++) {
            for (var j = 0; j < neededAPIs.length; j++) {
                if (exports[i].name === neededAPIs[j]) {
                    api[exports[i].name] = exports[i].address;
                }
            }
        }
        
        var foundCount = Object.keys(api).length;
        console.log("[+] Resolved " + foundCount + " IL2CPP API functions");
        
        if (!api.il2cpp_domain_get) {
            console.log("[-] Critical: il2cpp_domain_get not found!");
            console.log("[-] Available exports with 'il2cpp':");
            for (var i = 0; i < exports.length; i++) {
                if (exports[i].name.indexOf("il2cpp_") === 0) {
                    console.log("    " + exports[i].name);
                }
            }
            return;
        }
        
        // Create NativeFunctions for each resolved API
        var funcs = {};
        funcs.domain_get = new NativeFunction(api.il2cpp_domain_get, 'pointer', []);
        funcs.domain_get_assemblies = new NativeFunction(api.il2cpp_domain_get_assemblies, 'pointer', ['pointer', 'pointer']);
        funcs.assembly_get_image = new NativeFunction(api.il2cpp_assembly_get_image, 'pointer', ['pointer']);
        funcs.image_get_name = new NativeFunction(api.il2cpp_image_get_name, 'pointer', ['pointer']);
        funcs.image_get_class_count = new NativeFunction(api.il2cpp_image_get_class_count, 'int', ['pointer']);
        funcs.image_get_class = new NativeFunction(api.il2cpp_image_get_class, 'pointer', ['pointer', 'int']);
        funcs.class_get_name = new NativeFunction(api.il2cpp_class_get_name, 'pointer', ['pointer']);
        funcs.class_get_namespace = new NativeFunction(api.il2cpp_class_get_namespace, 'pointer', ['pointer']);
        funcs.class_get_type = new NativeFunction(api.il2cpp_class_get_type, 'pointer', ['pointer']);
        funcs.class_get_methods = new NativeFunction(api.il2cpp_class_get_methods, 'pointer', ['pointer', 'pointer']);
        funcs.class_get_fields = new NativeFunction(api.il2cpp_class_get_fields, 'pointer', ['pointer', 'pointer']);
        funcs.class_get_properties = new NativeFunction(api.il2cpp_class_get_properties, 'pointer', ['pointer', 'pointer']);
        funcs.class_get_parent = new NativeFunction(api.il2cpp_class_get_parent, 'pointer', ['pointer']);
        funcs.class_get_interfaces = new NativeFunction(api.il2cpp_class_get_interfaces, 'pointer', ['pointer', 'pointer']);
        funcs.class_get_nested_types = new NativeFunction(api.il2cpp_class_get_nested_types, 'pointer', ['pointer', 'pointer']);
        funcs.class_get_flags = new NativeFunction(api.il2cpp_class_get_flags, 'int', ['pointer']);
        funcs.class_is_enum = new NativeFunction(api.il2cpp_class_is_enum, 'bool', ['pointer']);
        funcs.class_is_valuetype = new NativeFunction(api.il2cpp_class_is_valuetype, 'bool', ['pointer']);
        funcs.class_from_type = new NativeFunction(api.il2cpp_class_from_type, 'pointer', ['pointer']);
        funcs.class_get_method_from_name = new NativeFunction(api.il2cpp_class_get_method_from_name, 'pointer', ['pointer', 'pointer', 'int']);
        funcs.class_get_field_from_name = new NativeFunction(api.il2cpp_class_get_field_from_name, 'pointer', ['pointer', 'pointer']);
        funcs.method_get_name = new NativeFunction(api.il2cpp_method_get_name, 'pointer', ['pointer']);
        funcs.method_get_flags = new NativeFunction(api.il2cpp_method_get_flags, 'int', ['pointer', 'pointer']);
        funcs.method_get_return_type = new NativeFunction(api.il2cpp_method_get_return_type, 'pointer', ['pointer']);
        funcs.method_get_param = new NativeFunction(api.il2cpp_method_get_param, 'pointer', ['pointer', 'int']);
        funcs.method_get_param_count = new NativeFunction(api.il2cpp_method_get_param_count, 'int', ['pointer']);
        funcs.method_get_param_name = new NativeFunction(api.il2cpp_method_get_param_name, 'pointer', ['pointer', 'int']);
        funcs.method_is_instance = new NativeFunction(api.il2cpp_method_is_instance, 'bool', ['pointer']);
        funcs.method_is_generic = new NativeFunction(api.il2cpp_method_is_generic, 'bool', ['pointer']);
        funcs.method_get_class = new NativeFunction(api.il2cpp_method_get_class, 'pointer', ['pointer']);
        funcs.type_get_name = new NativeFunction(api.il2cpp_type_get_name, 'pointer', ['pointer']);
        funcs.type_is_byref = new NativeFunction(api.il2cpp_type_is_byref, 'bool', ['pointer']);
        funcs.field_get_name = new NativeFunction(api.il2cpp_field_get_name, 'pointer', ['pointer']);
        funcs.field_get_type = new NativeFunction(api.il2cpp_field_get_type, 'pointer', ['pointer']);
        funcs.field_get_flags = new NativeFunction(api.il2cpp_field_get_flags, 'int', ['pointer']);
        funcs.field_get_offset = new NativeFunction(api.il2cpp_field_get_offset, 'int', ['pointer']);
        funcs.property_get_name = new NativeFunction(api.il2cpp_property_get_name, 'pointer', ['pointer']);
        funcs.property_get_get_method = new NativeFunction(api.il2cpp_property_get_get_method, 'pointer', ['pointer']);
        funcs.property_get_set_method = new NativeFunction(api.il2cpp_property_get_set_method, 'pointer', ['pointer']);
        funcs.thread_attach = api.il2cpp_thread_attach ? new NativeFunction(api.il2cpp_thread_attach, 'pointer', ['pointer']) : null;
        
        // Helper: read null-terminated string from pointer
        function readStr(ptr) {
            if (ptr.isNull()) return "<null>";
            return ptr.readUtf8String() || "<invalid>";
        }
        
        // Helper: get C# type name from IL2CPP type
        function getTypeName(typePtr) {
            if (typePtr.isNull()) return "void";
            var name = readStr(funcs.type_get_name(typePtr));
            return name;
        }
        
        // Helper: get method modifier string
        function getMethodModifier(flags) {
            var result = "";
            var access = flags & 0x7;
            switch (access) {
                case 1: result += "private "; break;
                case 6: result += "public "; break;
                case 4: result += "protected "; break;
                case 2: case 3: result += "internal "; break;
                case 5: result += "protected internal "; break;
            }
            if (flags & 0x10) result += "static ";
            if (flags & 0x400) result += "abstract ";
            if (flags & 0x200) result += "sealed ";
            if (flags & 0x40) result += "virtual ";
            if (flags & 0x2000) result += "extern ";
            return result;
        }
        
        // Helper: get field modifier string
        function getFieldModifier(flags) {
            var result = "";
            var access = flags & 0x7;
            switch (access) {
                case 1: result += "private "; break;
                case 6: result += "public "; break;
                case 4: result += "protected "; break;
                case 2: case 3: result += "internal "; break;
            }
            if (flags & 0x10) result += "static ";
            if (flags & 0x200) result += "readonly ";
            if (flags & 0x80) result += "const ";
            return result;
        }
        
        // Main dump function
        console.log("[*] Starting IL2CPP dump...");
        
        var domain = funcs.domain_get();
        if (domain.isNull()) {
            console.log("[-] Failed to get IL2CPP domain");
            return;
        }
        
        // Attach thread
        if (funcs.thread_attach) {
            funcs.thread_attach(domain);
        }
        
        // Get assemblies
        var sizePtr = Memory.alloc(8);
        sizePtr.writeU64(0);
        var assemblies = funcs.domain_get_assemblies(domain, sizePtr);
        var assemblyCount = sizePtr.readU32();
        
        console.log("[+] Found " + assemblyCount + " assemblies");
        
        // Output header
        var output = [];
        output.push("// IL2CPP Dump - Generated by OprekTool v0.16.0");
        output.push("// Frida Runtime Dumper");
        output.push("//");
        
        // List all assemblies
        for (var i = 0; i < assemblyCount; i++) {
            var image = funcs.assembly_get_image(assemblies.add(i * Process.pointerSize).readPointer());
            var imageName = readStr(funcs.image_get_name(image));
            output.push("// Image " + i + ": " + imageName);
        }
        output.push("");
        
        // Iterate all classes in all assemblies
        var totalClasses = 0;
        var totalMethods = 0;
        var totalFields = 0;
        
        for (var i = 0; i < assemblyCount; i++) {
            var image = funcs.assembly_get_image(assemblies.add(i * Process.pointerSize).readPointer());
            var imageName = readStr(funcs.image_get_name(image));
            var classCount = funcs.image_get_class_count(image);
            
            console.log("[*] Processing " + imageName + " (" + classCount + " classes)...");
            
            for (var j = 0; j < classCount; j++) {
                var klass = funcs.image_get_class(image, j);
                if (klass.isNull()) continue;
                
                var className = readStr(funcs.class_get_name(klass));
                var namespace = readStr(funcs.class_get_namespace(klass));
                var classFlags = funcs.class_get_flags(klass);
                var isEnum = funcs.class_is_enum(klass);
                var isValueType = funcs.class_is_valuetype(klass);
                
                // Skip compiler-generated types
                if (className.indexOf("<") !== -1 || className.indexOf("c__Iterator") !== -1 || className.indexOf("c__DisplayClass") !== -1) {
                    continue;
                }
                
                // Output class header
                output.push("// Namespace: " + namespace);
                
                var classMod = "";
                if ((classFlags & 0x20) && (classFlags & 0x100)) classMod = "static ";
                else if (classFlags & 0x20) classMod = "abstract ";
                else if (classFlags & 0x100) classMod = "sealed ";
                
                var classType = "class";
                if (isEnum) classType = "enum";
                else if (isValueType) classType = "struct";
                
                // Parent class
                var parent = funcs.class_get_parent(klass);
                var extends = "";
                if (!parent.isNull() && !isValueType && !isEnum) {
                    var parentName = readStr(funcs.class_get_name(parent));
                    if (parentName !== "Object" && parentName !== "ValueType" && parentName !== "Enum") {
                        extends = " : " + parentName;
                    }
                }
                
                // Interfaces
                var ifaceIter = Memory.alloc(8);
                ifaceIter.writePointer(NULL);
                var interfaces = "";
                while (true) {
                    var iface = funcs.class_get_interfaces(klass, ifaceIter);
                    if (iface.isNull()) break;
                    var ifaceName = readStr(funcs.class_get_name(iface));
                    if (interfaces === "") interfaces = " : " + ifaceName;
                    else interfaces += ", " + ifaceName;
                }
                if (interfaces !== "" && extends === "") extends = interfaces;
                else if (interfaces !== "") extends += interfaces;
                
                output.push(classMod + classType + " " + className + extends + " {");
                
                // Fields
                var fieldIter = Memory.alloc(8);
                fieldIter.writePointer(NULL);
                while (true) {
                    var field = funcs.class_get_fields(klass, fieldIter);
                    if (field.isNull()) break;
                    var fieldName = readStr(funcs.field_get_name(field));
                    var fieldType = funcs.field_get_type(field);
                    var fieldTypeName = readStr(funcs.type_get_name(fieldType));
                    var fieldFlags = funcs.field_get_flags(field);
                    var fieldMod = getFieldModifier(fieldFlags);
                    var fieldOffset = funcs.field_get_offset(field);
                    
                    output.push("    " + fieldMod + fieldTypeName + " " + fieldName + "; // 0x" + fieldOffset.toString(16));
                    totalFields++;
                }
                
                // Methods
                var methodIter = Memory.alloc(8);
                methodIter.writePointer(NULL);
                while (true) {
                    var method = funcs.class_get_methods(klass, methodIter);
                    if (method.isNull()) break;
                    var methodName = readStr(funcs.method_get_name(method));
                    var methodFlags = funcs.method_get_flags(method, NULL);
                    var methodMod = getMethodModifier(methodFlags);
                    
                    // Return type
                    var retType = funcs.method_get_return_type(method);
                    var retTypeName = readStr(funcs.type_get_name(retType));
                    
                    // Parameters
                    var paramCount = funcs.method_get_param_count(method);
                    var params = "";
                    for (var p = 0; p < paramCount; p++) {
                        var param = funcs.method_get_param(method, p);
                        var paramTypeName = readStr(funcs.type_get_name(param));
                        var paramName = readStr(funcs.method_get_param_name(method, p));
                        if (p > 0) params += ", ";
                        params += paramTypeName + " " + paramName;
                    }
                    
                    output.push("    " + methodMod + retTypeName + " " + methodName + "(" + params + ") { }");
                    totalMethods++;
                }
                
                // Properties
                var propIter = Memory.alloc(8);
                propIter.writePointer(NULL);
                while (true) {
                    var prop = funcs.class_get_properties(klass, propIter);
                    if (prop.isNull()) break;
                    var propName = readStr(funcs.property_get_name(prop));
                    var getMethod = funcs.property_get_get_method(prop);
                    var setMethod = funcs.property_get_set_method(prop);
                    
                    var propType = "var";
                    var propAccess = "";
                    if (!getMethod.isNull()) {
                        var getFlags = funcs.method_get_flags(getMethod, NULL);
                        propAccess = getMethodModifier(getFlags);
                        var getRetType = funcs.method_get_return_type(getMethod);
                        propType = readStr(funcs.type_get_name(getRetType));
                    } else if (!setMethod.isNull()) {
                        var setFlags = funcs.method_get_flags(setMethod, NULL);
                        propAccess = getMethodModifier(setFlags);
                        var setParam = funcs.method_get_param(setMethod, 0);
                        propType = readStr(funcs.type_get_name(setParam));
                    }
                    
                    var accessors = "";
                    if (!getMethod.isNull()) accessors += "get; ";
                    if (!setMethod.isNull()) accessors += "set; ";
                    
                    output.push("    " + propAccess + propType + " " + propName + " { " + accessors + "}");
                }
                
                output.push("}");
                output.push("");
                totalClasses++;
                
                if (totalClasses % 100 === 0) {
                    console.log("[*] Progress: " + totalClasses + " classes, " + totalMethods + " methods, " + totalFields + " fields");
                }
            }
        }
        
        console.log("[+] Dump complete!");
        console.log("[+] " + totalClasses + " classes, " + totalMethods + " methods, " + totalFields + " fields");
        
        // Save output
        var dumpContent = output.join("\n");
        var dumpPath = "/sdcard/Download/OprekTool/dump/dump_frida.cs";
        
        try {
            var dir = "/sdcard/Download/OprekTool/dump";
            // Use Java to write file
            Java.use("java.io.File").$new(dir).mkdirs();
            var writer = Java.use("java.io.FileWriter").$new(dumpPath);
            writer.write(dumpContent);
            writer.close();
            console.log("[+] Saved to: " + dumpPath);
        } catch(e) {
            console.log("[-] Failed to save file: " + e);
            console.log("[*] Printing dump to console instead:");
            console.log(dumpContent);
        }
        
        console.log("[+] Done! Use 'cat /sdcard/Download/OprekTool/dump/dump_frida.cs' to view.");
    }
});
